Esplicitiamo le componenti di
\[
  \STrie(T)\;=\;\bigl\langle\, Q\cup\{\bot\},\;\mathit{root},\;F,\;g,\;f \,\bigr\rangle .
\]
Se $x$ è una stringa, denotiamo con $\bar{x}$ lo stato associato ad $x$. Allora
\begin{align*}
  Q            &= \set{\bar{x} \;:\; x \text{ sottostringa di } T},\\
  \mathit{root}&= \bar{\vuota} \quad\text{(stato iniziale)},\\
  F            &= \set{\bar{x} \;:\; x \text{ è un suffisso di } T},\\
  g(\bar{x},a) &= \overline{xa}, \qquad g(\bot,a)=\mathit{root}
                  \quad \text{per ogni } a\in\S .
\end{align*}

\begin{osservazione}
Accanto alla riga di $F$ gli appunti annotano, con una freccia, la parola
«necessario»: è $F$ a fare di $\STrie(T)$ un automa che riconosce
\emph{esattamente} i suffissi di $T$, e non semplicemente le sue sottostringhe.
\end{osservazione}
